TLM.f("Tempora/Quad6-4rm2",{"officium":"Feria Quinta in Coena Domini","rule":["Gloria","Prefatio=Quad5","Communicantes","Post Missam","Maundi","Ter miserere","no Pax","no Qui dixisti","Benedicamus Domino","no Benedictio","no Ultima Evangelium"],"sections":{"Introitus":[{"k":"ref","la":"Gal 6:14"},{"k":"text","la":"Nos autem gloriári opórtet in Cruce Dómini nostri Jesu Christi: in quo est salus, vita et resurréctio nostra: per quem salváti et liberáti sumus."},{"k":"ref","la":"Ps 66:2"},{"k":"text","la":"Deus misereátur nostri, et benedícat nobis: illúminet vultum suum super nos, et misereátur nostri."},{"k":"text","la":"Nos autem gloriári opórtet in Cruce Dómini nostri Jesu Christi: in quo est salus, vita et resurréctio nostra: per quem salváti et liberáti sumus."}],"Oratio":[{"k":"text","la":"Deus, a quo et Judas reátus sui pœnam, et confessiónis suæ latro prǽmium sumpsit, concéde nobis tuæ propitiatiónis efféctum: ut, sicut in passióne sua Jesus Christus, Dóminus noster, divérsa utrísque íntulit stipéndia meritórum; ita nobis, abláto vetustátis erróre, resurrectiónis suæ grátiam largiátur:"},{"k":"macro","name":"Qui tecum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios."},{"k":"ref","la":"1 Cor 11:20-32"},{"k":"text","la":"Fratres: Conveniéntibus vobis in unum, jam non est Domínicam cœnam manducáre. Unusquísque enim suam cenam præsúmit ad manducándum. Et alius quidem ésurit: álius autem ébrius est. Numquid domos non habétis ad manducándum et bibéndum? aut ecclésiam Dei contémnitis, et confúnditis eos, qui non habent? Quid dicam vobis? Laudo vos? In hoc non laudo. Ego enim accépi a Dómino quod et trádidi vobis, quóniam Dóminus Jesus, in qua nocte tradebátur, accépit panem, et grátias agens fregit, et dixit: Accípite, et manducáte: hoc est corpus meum, quod pro vobis tradétur: hoc fácite in meam commemoratiónem. Simíliter et cálicem, postquam cœnávit, dicens: Hic calix novum Testaméntum est in meo sánguine: hoc fácite, quotiescúmque bibétis, in meam commemoratiónem. Quotiescúmque enim manducábitis panem hunc et cálicem bibétis: mortem Dómini annuntiábitis, donec véniat. Itaque quicúmque manducáverit panem hunc vel bíberit cálicem Dómini indígne, reus erit córporis et sánguinis Dómini. Probet autem seípsum homo: et sic de pane illo edat et de cálice bibat. Qui enim mandúcat et bibit indígne, judícium sibi mandúcat et bibit: non dijúdicans corpus Dómini. Ideo inter vos multi infirmi et imbecílles, et dórmiunt multi. Quod si nosmetípsos dijudicarémus, non útique judicarémur. Dum judicámur autem, a Dómino corrípimur, ut non cum hoc mundo damnémur."}],"Graduale":[{"k":"ref","la":"Phil 2:8-9"},{"k":"text","la":"Christus factus est pro nobis obœ́diens usque ad mortem, mortem autem crucis."},{"k":"text","la":"Propter quod et Deus exaltávit illum: et dedit illi nomen, quod est super omne nomen.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem."},{"k":"ref","la":"Joann 13:1-15"},{"k":"text","la":"Ante diem festum Paschæ, sciens Jesus, quia venit hora ejus, ut tránseat ex hoc mundo ad Patrem: cum dilexísset suos, qui erant in mundo, in finem diléxit eos. Et cena facta, cum diábolus jam misísset in cor, ut tráderet eum Judas Simónis Iscariótæ: sciens, quia ómnia dedit ei Pater in manus, et quia a Deo exivit, et ad Deum vadit: surgit a cena et ponit vestiménta sua: et cum accepísset línteum, præcínxit se. Deinde mittit aquam in pelvim, et cœpit laváre pedes discipulórum, et extérgere línteo, quo erat præcínctus. Venit ergo ad Simónem Petrum. Et dicit ei Petrus: Dómine, tu mihi lavas pedes? Respóndit Jesus et dixit ei: Quod ego fácio, tu nescis modo, scies autem póstea. Dicit ei Petrus: Non lavábis mihi pedes in ætérnum. Respóndit ei Jesus: Si non lávero te, non habébis partem mecum. Dicit ei Simon Petrus: Dómine, non tantum pedes meos, sed et manus et caput. Dicit ei Jesus: Qui lotus est, non índiget nisi ut pedes lavet, sed est mundus totus. Et vos mundi estis, sed non omnes. Sciébat enim, quisnam esset, qui tráderet eum: proptérea dixit: Non estis mundi omnes. Postquam ergo lavit pedes eórum et accépit vestiménta sua: cum recubuísset íterum, dixit eis: Scitis, quid fécerim vobis? Vos vocátis me Magíster et Dómine: et bene dícitis: sum étenim. Si ergo ego lavi pedes vestros, Dóminus et Magíster: et vos debétis alter altérius laváre pedes. Exémplum enim dedi vobis, ut, quemádmodum ego feci vobis, ita et vos faciátis."}],"Offertorium":[{"k":"ref","la":"Ps 117:16 et 17"},{"k":"text","la":"Déxtera Dómini fecit virtútem, déxtera Dómini exaltávit me: non móriar, sed vivam, et narrábo ópera Dómini."}],"Secreta":[{"k":"text","la":"Ipse tibi, quǽsumus, Dómine sancte, Pater omnípotens, ætérne Deus, sacrifícium nostrum reddat accéptum, qui discípulis suis in sui commemoratiónem hoc fíeri hodiérna traditióne monstrávit, Jesus Christus, Fílius tuus, Dóminus noster:"},{"k":"macro","name":"Qui tecum"}],"Communio":[{"k":"ref","la":"Joann 13:12, 13 et 15"},{"k":"text","la":"Dóminus Jesus, postquam cœnávit cum discípulis suis, lavit pedes eórum, et ait illis: Scitis, quid fécerim vobis ego, Dóminus et Magíster? Exemplum dedi vobis, ut et vos ita faciátis."}],"Postcommunio":[{"k":"text","la":"Refécti vitálibus aliméntis, quǽsumus, Dómine, Deus noster: ut, quod témpore nostræ mortalitátis exséquimur, immortalitátis tuæ múnere consequámur."},{"k":"macro","name":"Per Dominum"}],"Maundi":[{"k":"head","la":"De lotione pedum"},{"k":"rubric","la":"Post homiliam proceditur, ubi ratio ! pastoralis id suadeat, ad lotionem pedum."},{"k":"rubric","la":"In medio presbyterii, vel in ipsa aula ! ecclesiæ, parata sint sedilia hinc inde pro ! duodecim viris, quorum lavabuntur pedes; ! cetera quæ occurrunt, tempore opportuno, ! in mensula parentur."},{"k":"rubric","la":"Interim diaconus et subdiaconus, seu ! duo maiores ex ministrantibus, inducunt duodecim ! viros selectos, binos et binos, ad locum ! paratum, dum schola vel ipse clerus ! assistens incipit, cantando vel recitando, ! antiphonas, psalmos et versus infrascriptos."},{"k":"rubric","la":"Duodecim autem viri selecti, facta reverentia ! altari ac celebranti, in presbyterio ! sedenti, disponuntur per sedilia; tunc ministri ! sacri, seu ministrantes, adibunt celebrantem. ! Omnes deponunt manipulum, celebrans ! vero etiam planetam."},{"k":"rubric","la":"Lotione pedum ad finem vergente, incipitur ! antiphona 8a cum suis versibus, ceteris, ! si opus sit, omissis."},{"k":"sep"},{"k":"ref","la":"Antiphona 1"},{"k":"ref","la":"Joann 13:34"},{"k":"text","la":"Ant. Mandátum novum do vobis: ut diligátis ínvicem, sicut diléxi vos, dicit Dóminus."},{"k":"ref","la":"Ps 118:1"},{"k":"text","la":"Beáti immaculáti in via: qui ámbulant in lege Dómini."},{"k":"rubric","la":"Et repetitur immediate antiphona «Mandatum novum»."},{"k":"text","la":"Ant. Mandátum novum do vobis: ut diligátis ínvicem, sicut diléxi vos, dicit Dóminus."},{"k":"rubric","la":"Et sic aliæ antiphonæ, quæ ! habent psalmos vel versus, repetuntur. Et ! de quolibet psalmo dicitur tantum primus ! versus."},{"k":"sep"},{"k":"ref","la":"Antiphona 2"},{"k":"ref","la":"Joann 13:4, 5 et 15"},{"k":"text","la":"Ant. Postquam surréxit Dóminus a cœna, misit aquam in pelvim, et cœpit laváre pedes discipulórum suórum: hoc exémplum réliquit eis."},{"k":"ref","la":"Ps 47:2"},{"k":"text","la":"Magnus Dóminus, et laudábilis nimis: in civitáte Dei nostri, in monte sancto ejus."},{"k":"text","la":"Ant. Postquam surréxit Dóminus a cœna, misit aquam in pelvim, et cœpit laváre pedes discipulórum suórum: hoc exémplum réliquit eis."},{"k":"sep"},{"k":"ref","la":"Antiphona 3"},{"k":"ref","la":"Joann 13:12, 13 et 15"},{"k":"text","la":"Ant. Dóminus Jesus, postquam cenávit cum discípulis suis, lavit pedes eórum, et ait illis: «Scitis, quid fécerim vobis ego, Dóminus et Magíster? Exémplum dedi vobis, ut et vos ita faciátis»."},{"k":"ref","la":"Ps 84:2"},{"k":"text","la":"Benedixísti, Dómine, terram tuam: avertísti captivitátem Jacob."},{"k":"text","la":"Ant. Dóminus Jesus, postquam cenávit cum discípulis suis, lavit pedes eórum, et ait illis: «Scitis, quid fécerim vobis ego, Dóminus et Magíster? Exémplum dedi vobis, ut et vos ita faciátis»."},{"k":"sep"},{"k":"ref","la":"Antiphona 4"},{"k":"ref","la":"Joann 13:6-7 et 8"},{"k":"text","la":"Ant. «Dómine, tu mihi lavas pedes?» Respóndit Jesus et dixit ei: «Si non lávero tibi pedes, non habébis partem mecum»."},{"k":"text","la":"Venit ergo ad Simónem Petrum, et dixit ei Petrus.","mark":"V"},{"k":"text","la":"Ant. «Dómine, tu mihi lavas pedes?» Respóndit Jesus et dixit ei: «Si non lávero tibi pedes, non habébis partem mecum»."},{"k":"text","la":"«Quod ego fácio, tu nescis modo: scies autem póstea».","mark":"V"},{"k":"text","la":"Ant. «Dómine, tu mihi lavas pedes?» Respóndit Jesus et dixit ei: «Si non lávero tibi pedes, non habébis partem mecum»."},{"k":"sep"},{"k":"ref","la":"Antiphona 5"},{"k":"ref","la":"Joann 13:14"},{"k":"text","la":"Ant. «Si ego, Dóminus et Magíster vester, lavi vobis pedes: quanto magis debétis alter altérius laváre pedes?»"},{"k":"ref","la":"Ps 48:2"},{"k":"text","la":"Audíte hæc, omnes gentes: áuribus percípite, qui habitátis orbem."},{"k":"text","la":"Ant. «Si ego, Dóminus et Magíster vester, lavi vobis pedes: quanto magis debétis alter altérius laváre pedes?»"},{"k":"sep"},{"k":"ref","la":"Antiphona 6"},{"k":"ref","la":"Joann 13:35"},{"k":"text","la":"Ant. «In hoc cognóscent omnes, quia discípuli mei estis, si dilectiónem habuéritis ad ínvicem»."},{"k":"text","la":"Dixit Jesus discípulis suis.","mark":"V"},{"k":"text","la":"Ant. «In hoc cognóscent omnes, quia discípuli mei estis, si dilectiónem habuéritis ad ínvicem»."},{"k":"sep"},{"k":"ref","la":"Antiphona 7"},{"k":"ref","la":"1 Cor 13:13"},{"k":"text","la":"Ant. Máneant in vobis fides, spes, cáritas, tria hæc: major autem horum est cáritas."},{"k":"text","la":"Nunc autem manent fides, spes, cáritas, tria hæc: major horum est cáritas.","mark":"V"},{"k":"text","la":"Ant. Máneant in vobis fides, spes, cáritas, tria hæc: major autem horum est cáritas."},{"k":"sep"},{"k":"ref","la":"Antiphona 8"},{"k":"rubric","la":"Sequens antiphona cum suis versibus ! numquam omittitur; incipitur autem, omissis, ! si opus sit, præcedentibus, lotione pedum ! ad finem vergente."},{"k":"text","la":"Ubi cáritas et amor, Deus ibi est."},{"k":"text","la":"Congregávit nos in unum Christi amor.","mark":"V"},{"k":"text","la":"Exsultémus et in ipso jucundémur.","mark":"V"},{"k":"text","la":"Timeámus et amémus Deum vivum.","mark":"V"},{"k":"text","la":"Et ex corde diligámus nos sincéro.","mark":"V"},{"k":"text","la":"Ubi cáritas et amor, Deus ibi est."},{"k":"text","la":"Simul ergo cum in unum congregámur:","mark":"V"},{"k":"text","la":"Ne nos mente dividámur, caveámus.","mark":"V"},{"k":"text","la":"Cessent júrgia malígna, cessent lites.","mark":"V"},{"k":"text","la":"Et in médio nostri sit Christus Deus.","mark":"V"},{"k":"text","la":"Ubi cáritas et amor, Deus ibi est."},{"k":"text","la":"Simul quoque cum Beátis videámus","mark":"V"},{"k":"text","la":"Gloriánter vultum tuum, Christe Deus:","mark":"V"},{"k":"text","la":"Gáudium, quod est imménsum atque probum,","mark":"V"},{"k":"text","la":"Sǽcula per infiníta sæculórum. Amen.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Interim celebrans procedit ad lotionem ! pedum, hoc modo: præcingit se linteo, ! et per ordinem dispositis iis, qui lavandi ! sunt, acolythis pelvim et aquam ministrantibus, ! subdiacono singulorum pedem dextrum ! tenente, genuflectens singulis, illorum ! pedem lavat et extergit, diacono præbente ! linteum ad abstergendum."},{"k":"rubric","la":"Officia, quæ in ritu solemni a diacono ! et subdiacono adimplentur, a ministrantibus ! peraguntur."},{"k":"rubric","la":"Post lotionem celebrans lavat et abstergit ! manus, nihil dicens. Deinde omnes ! resumunt manipulum, celebrans vero etiam ! planetam, et redeunt ante medium altaris, ! ubi celebrans, versus populum, dicit:"},{"k":"sep"},{"k":"macro","name":"Pater noster"},{"k":"text","la":"Tu mandásti mandáta tua, Dómine.","mark":"V"},{"k":"text","la":"Custodíri nimis.","mark":"R"},{"k":"text","la":"Tu lavásti pedes discipulórum tuórum.","mark":"V"},{"k":"text","la":"Opera mánuum tuárum ne despícias.","mark":"R"},{"k":"text","la":"Dómine, exáudi oratiónem meam.","mark":"V"},{"k":"text","la":"Et clamor meus ad te véniat.","mark":"R"},{"k":"text","la":"Dóminus vobíscum.","mark":"V"},{"k":"text","la":"Et cum spíritu tuo.","mark":"R"},{"k":"text","la":"Orémus."},{"k":"text","la":"Adésto, Dómine, quǽsumus, offício servitútis nostræ: et quia tu discípulis tuis pedes laváre dignátus es, ne despícias ópera mánuum tuárum, quæ nobis retinénda mandásti: ut, sicut hic nobis, et a nobis exterióra abluúntur inquinaménta; sic a te ómnium nostrum interióra lavéntur peccáta. Quod ipse præstáre dignéris, qui vivis et regnas Deus: per ómnia sǽcula sæculórum."},{"k":"text","la":"Amen.","mark":"R"},{"k":"rubric","la":"Oratione completa, duodecim viri, facta ! reverentia altari et celebranti, reducuntur ! ad loca sua, si sint clerici in presbyterium, ! si sint laici in peculiarem locum ad hoc designatum."},{"k":"rubric","la":"Ubi vero contingat lotionem pedum ! extra Missarum solemnia peragi, observetur ! ordo supra descriptus, præmisso, cum ! solitis cæremoniis, cantu Evangelii Missæ ! Ante diem festum Paschæ, ut supra."},{"k":"rubric","la":"Post pedum lotionem, seu, ubi hæc ! locum non habuerit, post homiliam, proceditur ! in celebratione Missæ, more solito."}],"Post Missam":[{"k":"head","la":"Pange Lingua"},{"k":"rubric","la":"Missa expleta, statim proceditur ad ! solemnem translationem et repositionem ! Sacramenti, quod ad Communionem sequenti ! die faciendam in pyxide asservatur."},{"k":"rubric","la":"Pro solemni Sacramenti repositione ! paretur locus aptus in aliquo sacello vel altari ! ecclesiæ, ac decenter, quoad fieri potest, ! ornetur velis et luminaribus; atque, servatis ! Sacræ Rituum Congregationis decretis ! de vitandis vel tollendis abusibus in hoc ! loco parando, plane commendatur severitas ! quæ liturgiæ horum dierum convenit."},{"k":"rubric","la":"In translatione et repositione vero ! Sacramenti proceditur hoc modo: ! Accenduntur intorticia, et fit processio ! more solito. ! Si haberi potest, alius subdiaconus paratus ! ferat crucem; secus unus ex clericis vel ! ministrantibus. ! Celebrans, stans ante altare, imponit ! incensum in duobus thuribulis, absque ! benedictione. Deinde, in medio genuflexus, ter ! incensat Sacramentum. ! Tunc assumit velum humerale albi ! coloris, et ascendens altare in medio, facta ! genuflexione, stans, accipit pyxidem, quam ! diaconus ei porrigit, et extremitatibus veli ! cooperit. ! Deinde, de altari descendens, procedit ! sub baldachino, duobus acolythis, vel ! ministrantibus, Sacramentum continue ! incensantibus, usque ad locum paratum. ! Ministri sacri, vel ministrantes, comitantur ! celebrantem, a dextris et a sinistris ! procedentes. ! Dum fit processio, cantatur hymnus Pange, ! lingua, gloriosi Corporis mysterium, ! usque ad verba Tantum ergo; si vero opus ! sit, idem hymnus repetitur."},{"k":"sep"},{"k":"text","la":"Pange língua, gloriósi"},{"k":"text","la":"Córporis mystérium,"},{"k":"text","la":"Sanguinísque pretiósi,"},{"k":"text","la":"Quem in mundi prétium"},{"k":"text","la":"Fructus ventris generósi"},{"k":"text","la":"Rex effúdit géntium."},{"k":"sep"},{"k":"text","la":"Nobis datus, nobis natus"},{"k":"text","la":"Ex intácta Vírgine,"},{"k":"text","la":"Et in mundo conversátus,"},{"k":"text","la":"Sparso verbi sémine."},{"k":"text","la":"Sui moras incolátus."},{"k":"text","la":"Miro clausit órdine."},{"k":"sep"},{"k":"text","la":"In suprémæ nocte cœnæ"},{"k":"text","la":"Recúmbens cum frátribus,"},{"k":"text","la":"Observáta lege plene"},{"k":"text","la":"Cibis in legálibus,"},{"k":"text","la":"Cibum turbæ duodénæ"},{"k":"text","la":"Se dat suis mánibus."},{"k":"sep"},{"k":"text","la":"Verbum caro, panem verum"},{"k":"text","la":"Verbo carnem éfficit;"},{"k":"text","la":"Fitque sanguis Christi merum:"},{"k":"text","la":"Et si sensus déficit,"},{"k":"text","la":"Ad firmándum cor sincérum"},{"k":"text","la":"Sola fides súfficit."},{"k":"sep"},{"k":"rubric","la":"Cum autem ventum fuerit ad locum ! paratum, celebrans, adiuvante, si opus sit, ! diacono, deponit pyxidem super altare, ! genuflectit, et incensat, thure iterum imposito ! interim canitur Tantum ergo."},{"k":"text","la":"Tantum ergo Sacraméntum"},{"k":"text","la":"Venerémur cérnui:"},{"k":"text","la":"Et antíquum documéntum"},{"k":"text","la":"Novo cedat ritui:"},{"k":"text","la":"Præstet fides supplémentum"},{"k":"text","la":"Sénsuum deféctui."},{"k":"sep"},{"k":"text","la":"Genitóri, Genitóque"},{"k":"text","la":"Laus et iubilátio:"},{"k":"text","la":"Salus, honor, virtus quoque"},{"k":"text","la":"Sit et benedíctio"},{"k":"text","la":"Procedénti ab utróque"},{"k":"text","la":"Compar sit laudátio."},{"k":"text","la":"Amen."},{"k":"sep"},{"k":"rubric","la":"Deinde diaconus, vel ipse celebrans, ! reponit pyxidem in tabernaculo seu capsa."},{"k":"sep"},{"k":"rubric","la":"Postea, omnes, genibus flexis, per ! aliquod temporis spatium in silentio Sacramentum ! adorant. Signo dato, celebrans et ! ministri sacri, et ministrantes, surgunt, ! iterum, genibus flexis, adorant, et revertuntur ! in sacristiam, ubi celebrans et ministri sacri ! deponunt paramenta albi coloris; deinde ! celebrans et diaconus assumunt stolam ! violaceam."},{"k":"sep"},{"k":"rubric","la":"Si autem plures pyxides transferendæ ! sint, idem celebrans (vel, si habeantur, alius ! sacerdos, aut diaconus, indutus superpelliceo ! stola alba et velo humerali eiusdem ! coloris) eas transferat ad locum destinatum, ! antequam incipiat altarium denudationem, ! forma quidem simplici, scilicet comitantibus ! duobus acolythis, vel ministrantibus, cum ! cereis accensis, alioque umbellam portante."},{"k":"sep"},{"k":"head","la":"Denudatione altaris"},{"k":"sep"},{"k":"rubric","la":"Deinde celebrans et ministri, seu ! ministrantes, exeunt ante altare maius; facta ! eidem reverentia, stantes, incipiunt ! denudationem altarium, hoc modo: ! Celebrans dicit clara voce sequentem ! antiphonam:"},{"k":"sep"},{"k":"rubric","la":"Antiphona"},{"k":"ref","la":"Ps 21:19"},{"k":"text","la":"Ant. Divisérunt sibi vestiménta mea: et super vestem meam misérunt sortem."},{"k":"text","la":"(21:2) Deus, Deus meus, réspice in me: quare me dereliquísti? * longe a salúte mea verba delictórum meórum."},{"k":"text","la":"(21:3) Deus meus, clamábo per diem, et non exáudies: * et nocte, et non ad insipiéntiam mihi."},{"k":"text","la":"(21:4) Tu autem in sancto hábitas, * laus Israël."},{"k":"text","la":"(21:5) In te speravérunt patres nostri: * speravérunt, et liberásti eos."},{"k":"text","la":"(21:6) Ad te clamavérunt, et salvi facti sunt: * in te speravérunt, et non sunt confúsi."},{"k":"text","la":"(21:7) Ego autem sum vermis, et non homo: * oppróbrium hóminum, et abjéctio plebis."},{"k":"text","la":"(21:8) Omnes vidéntes me, derisérunt me: * locúti sunt lábiis, et movérunt caput."},{"k":"text","la":"(21:9) Sperávit in Dómino, erípiat eum: * salvum fáciat eum, quóniam vult eum."},{"k":"text","la":"(21:10) Quóniam tu es, qui extraxísti me de ventre: * spes mea ab ubéribus matris meæ. In te projéctus sum ex útero:"},{"k":"text","la":"(21:11) De ventre matris meæ Deus meus es tu, * ne discésseris a me:"},{"k":"text","la":"(21:12) Quóniam tribulátio próxima est: * quóniam non est qui ádjuvet."},{"k":"text","la":"(21:13) Circumdedérunt me vítuli multi: * tauri pingues obsedérunt me."},{"k":"text","la":"(21:14) Aperuérunt super me os suum, * sicut leo rápiens et rúgiens."},{"k":"text","la":"(21:15) Sicut aqua effúsus sum: * et dispérsa sunt ómnia ossa mea."},{"k":"text","la":"(21:15) Factum est cor meum tamquam cera liquéscens * in médio ventris mei."},{"k":"text","la":"(21:16) Aruit tamquam testa virtus mea, et lingua mea adhæsit fáucibus meis: * et in púlverem mortis deduxísti me."},{"k":"text","la":"(21:17) Quóniam circumdedérunt me canes multi: * concílium malignántium obsédit me."},{"k":"text","la":"(21:18) Fodérunt manus meas et pedes meos: * dinumeravérunt ómnia ossa mea."},{"k":"text","la":"(21:19) Ipsi vero consideravérunt et inspexérunt me: * divisérunt sibi vestiménta mea, et super vestem meam misérunt sortem."},{"k":"text","la":"(21:20) Tu autem, Dómine, ne elongáveris auxílium tuum a me: * ad defensiónem meam cónspice."},{"k":"text","la":"(21:21) Erue a frámea, Deus, ánimam meam: * et de manu canis únicam meam:"},{"k":"text","la":"(21:22) Salva me ex ore leónis: * et a córnibus unicórnium humilitátem meam."},{"k":"text","la":"(21:23) Narrábo nomen tuum frátribus meis: * in médio ecclésiæ laudábo te."},{"k":"text","la":"(21:24) Qui timétis Dóminum, laudáte eum: * univérsum semen Jacob, glorificáte eum."},{"k":"text","la":"(21:25) Tímeat eum omne semen Israël: * quóniam non sprevit, neque despéxit deprecatiónem páuperis:"},{"k":"text","la":"(21:25) Nec avértit fáciem suam a me: * et cum clamárem ad eum, exaudívit me."},{"k":"text","la":"(21:26) Apud te laus mea in ecclésia magna: * vota mea reddam in conspéctu timéntium eum."},{"k":"text","la":"(21:27) Edent páuperes, et saturabúntur: et laudábunt Dóminum qui requírunt eum: * vivent corda eórum in sǽculum sǽculi."},{"k":"text","la":"(21:28) Reminiscéntur et converténtur ad Dóminum * univérsi fines terræ:"},{"k":"text","la":"(21:28) Et adorábunt in conspéctu ejus * univérsæ famíliæ géntium."},{"k":"text","la":"(21:29) Quóniam Dómini est regnum: * et ipse dominábitur géntium."},{"k":"text","la":"(21:30) Manducavérunt et adoravérunt omnes pingues terræ: * in conspéctu ejus cadent omnes qui descéndunt in terram."},{"k":"text","la":"(21:31) Et ánima mea illi vivet: * et semen meum sérviet ipsi."},{"k":"text","la":"(21:32) Annuntiábitur Dómino generátio ventúra: * et annuntiábunt cœli justítiam ejus pópulo qui nascétur, quem fecit Dóminus."},{"k":"text","la":"Ant. Divisérunt sibi vestiménta mea: et super vestem meam misérunt sortem."},{"k":"sep"},{"k":"rubric","la":"Clerici, si adsunt, prosequuntur recitationem ! huius psalmi, usque dum altarium ! denudatio peracta sit; alioquin celebrans dicat ! antiphonam et primum tantum versum ! psalmi ante denudationem altaris maioris. ! Celebrans vero cum ministris sacris, vel ! ministrantibus, denudat omnia altaria ! ecclesiæ, excepto illo in quo Sacramentum ! solemniter adoratur. ! Altaribus denudatis, redeunt ad altare ! maius, et, repetita a celebrante antiphona ! Dividunt, revertuntur in sacristiam."},{"k":"sep"},{"k":"rubric","la":"Mox in choro dicitur Completorium, ! candelis exstinctis et absque cantu."},{"k":"sep"},{"k":"rubric","la":"Ad locum autem repositionis sanctissimæ ! Eucharistiæ fit publica adoratio, inde ! ab expleta Missa in Cena Domini instituenda ! et protrahenda saltem usque ad ! mediam noctem."}],"Communicantes":[{"k":"text","la":"Communicántes et diem sacratíssimum celebrántes, quo Dóminus noster Jesus Christus pro nobis est tráditus: sed et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis ejúsdem Dei et Dómini nostri Jesu Christi: sed"},{"k":"text","la":"et beati Ioseph, eiusdem Virginis Sponsi,"},{"k":"text","la":"et beatórum Apostolórum ac Mártyrum tuórum, Petri et Pauli, Andréæ, Jacóbi, Joánnis, Thomæ, Jacóbi, Philíppi, Bartholomæi, Matthæi, Simónis et Thaddæi: Lini, Cleti, Cleméntis, Xysti, Cornélii, Cypriáni, Lauréntii, Chrysógoni, Joánnis et Pauli, Cosmæ et Damiáni: et ómnium Sanctórum tuórum; quorum méritis precibúsque concédas, ut in ómnibus protectiónis tuæ muniámur auxílio. (Jungit manus.) Per eúndem Christum, Dóminum nostrum. Amen."},{"k":"sep"},{"k":"rubric","la":"Tenens manus expansas super Oblata, dicit:"},{"k":"text","la":"Hanc ígitur oblatiónem servitútis nostræ, sed et cunctæ famíliæ tuæ, quam tibi offérimus ob diem, in qua Dóminus noster Jesus Christus trádidit discípulis suis Córporis et Sánguinis sui mystéria celebránda: quǽsumus, Dómine, ut placátus accípias: diésque nostros in tua pace dispónas, atque ab ætérna damnatióne nos éripi et in electórum tuórum júbeas grege numerári. (Jungit manus) Per eúndem Christum, Dóminum nostrum. Amen."},{"k":"sep"},{"k":"text","la":"Quam oblatiónem tu, Deus, in ómnibus, quǽsumus, (Signat ter super Oblata,) bene + díctam, adscríp + tam, ra + tam, rationábilem acceptabilémque fácere dignéris: (Signat semel super Hóstiam,) ut nobis Cor + pus, (et semel super Cálicem,) et San + guis fiat dilectíssimi Fílii tui, (Jungit manus), Dómini nostri Jesu Christi."},{"k":"sep"},{"k":"text","la":"Qui prídie, quam pro nostra omniúmque salúte paterétur, hoc est hódie, (Accipit Hostiam,) accépit panem in sanctas ac venerábiles manus suas, (Elevat oculos ad cœlum,) et elevátis óculis in cœlum ad te Deum, Patrem suum omnipoténtem, (Caput inclinat,) tibi grátias agens, (Signat super Hostiam,) bene + dixit, fregit, dedítque discípulis suis, dicens: Accípite, et manducáte ex hoc omnes."}]},"hr":{"22d0eb1edc277857":{"t":"Gal 6, 14, Ps 66, 2\n(Gal 6, 14) Mi treba da se dičimo križem Gospodina našega Isusa Krista. U njemu je naše spasenje, život i uskrsnuće. Po njemu smo spašeni i izbavljeni. (Ps 66, 2) Nek nam se smiluje Bog i neka nas blagoslovi! Neka naš obasja svojim licem i nek nam se smiluje! (Gal 6, 14) Mi treba da se dičimo križem Gospodina našega Isusa Krista. U njemu je naše spasenje, život i uskrsnuće. Po njemu smo spašeni i izbavljeni. [u vremenu Muke ne govori se Slava Ocu u sklopu Ulazne pjesme]"},"acfecb17fa47b144":{"t":"<i>Pomolimo se</i>.\n<i>Prignimo koljena. - Ustanite</i>.\nBože, od koga je Juda dobio kaznu za svoj zločin i razbojnik nagradu za svoje priznanje, podaj nam plod svoga pomilovanja, kao što je Isus Krist, Gospodin naš, u svojoj muci obojici različito po zasluzi naplatio, tako neka i nama uklonivši staru zabludu udijeli milost svoga uskrsnuća:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"1a00ed79488c5438":{"t":"1 Kor 11, 20-32\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo: Kad se sastajete zajedno to nije više blagovanje Gospodinove večere. Svaki, naime, najprije jede svoju večeru, pa tako jedan gladuje, a drugi se opija. Zar nemate kuća da jedete i pijete? Ili prezirete crkvu Božju i posramljujete one koji nemaju? Što da vam kažem? Da vas pohvalim? U tome vas ne hvalim. Jer ja sam primio od Gospodina što sam vam i predao, da Gospodin Isus one noći u kojoj je bio izdan, uze kruh, zahvali, prelomi i reče: »Uzmite i jedite: ovo je tijelo moje koje će se za vas predati. Ovo činite na moju uspomenu.« A tako i čašu po večeri govoreći: »Ova je čaša novi zavjet u mojoj krvi. Ovo činite kad god pijete na moju uspomenu.« Kad god, naime, budete ovaj kruh jeli i čašu pili, navješćivat ćete smrt Gospodinovu dok on dođe. Stoga tko god bude nedostojno jeo ovaj kruh ili pio čašu Gospodinovu, bit će krivac tijelu i krvi Gospodinovoj. Neka dakle čovjek ispita sam sebe, pa onda neka od onoga kruha jede i od čaše pije. Jer tko jede i pije nedostojno, osudu sebi jede i pije ne razlikujući tijela Gospodinova. Zato su među vama mnogi slabi i bolesni, mnogi su pospani. Jer kad bismo sami sebe prosuđivali, sigurno ne bismo bili osuđeni. Ali, kad nam se sudi, Gospodin nas kažnjava, da ne budemo osuđeni s ovim svijetom."},"a196c2580ecc0267":{"t":"Fil 2, 8-9\nKrist je postao za nas poslušan sve do smrti i to do smrti na križu. Zato Bog njega uzvisi i darova mu ime, koje je nad svakim imenom."},"9e85a566cd6bb8c4":{"t":"Iv 13, 1-15\nSlijedi sveto Evanđelje po Ivanu. Pred blagdan Vazma, znajući Isus da je došao njegov čas, da pođe s ovoga svijeta k Ocu, jer je ljubio svoje koji bijahu na svijetu, do kraja ih je ljubio. Pa poslije večere, kad je đavao već bio stavio u srce Jude sina Šimuna Iskariota da ga izda, znajući, da mu je Otac sve dao u ruke i da je od Boga izišao i da ide k Bogu, ustade od večere, skine svoju haljinu, pa uze prati noge učenicima i otirati ručnikom kojim je bio opasan. Kad je došao k Šimunu Petru, reče mu Petar: Gospodine, zar da mi ti pereš noge? Isus mu odgovori: Što ja činim ti ne znaš sada, ali ćeš znati poslije. Veli mu Petar: Nikad ti meni nećeš prati noge. Odgovori mu Isus: Ako te ne operem, nećeš imati dijela sa mnom. Reče mu Šimun Petar: Gospodine, ne samo moje noge, nego i ruke i glavu. Veli mu Isus: Tko je opran, ne treba nego da samo opere noge, pa je sav čist. I vi ste čisti, ali ne svi. Jer je znao, tko će ga izdati, zato je rekao: Niste svi čisti. A pošto im je oprao noge i uzeo svoju haljinu, sjede ponovo za stol pa im reče: Znate li što sam vam učinio? Vi zovete mene Učiteljem i Gospodinom i dobro govorite, jer to jesam. Kad sam vam dakle ja, Gospodin i Učitelj, oprao noge i vi morate jedan drugome prati noge. Jer vam dadoh primjer da i vi tako činite, kao što ja učinili vama."},"a63cb5f96fa870c3":{"t":"Ps 117, 16-17\nDesnica Gospodnja učini čudo, desnica me Gospodnja podiže! Neću umrijeti nego živjeti i naviještati djela Gospodnja."},"1537c49707a54798":{"t":"Našu žrtvu, molimo, Gospodine, sveti Oče, svemogući vječni Bože, neka učini tebi ugodnom sam onaj koji je na današnji dan ovo naredio i poučio svoje učenike da se to čini njemu na spomen, Isus Krist, Sin tvoj, Gospodin naš:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"f2fb1fe68f386b18":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti si odredio spasenje ljudskog roda po drvu Križa, da se opet rodi život ondje gdje je nikla smrt, i onaj koji je na drvu pobijedio, bude pobijeđen na drvu po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glas primi dok govorimo poniznim hvalospjevom:"},"282ff17ac7f0b346":{"t":"Iv 13, 12 i 13 i 15\nKad je Gospodin Isus večerao sa svojim učenicima, oprao im je noge i rekao: Znate li, što sam vam učinio ja, Gospodin i Učitelj? Dao sam vam primjer da i vi tako činite!"},"bd8a5851e73eb7a9":{"t":"<i>Pomolimo se</i>.\nOkrijepljeni životvornom hranom molimo, Gospodine Bože naš, da ono što svetkujemo za svoga smrtnog života postignemo darom tvoje besmrtnosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
